  0x1000756a0:  08c10291       add      x8, x8, #0xb0 ; "#!/usr/bin/env python3
import json, os, socket, sys

SOCK_PATH = os.path.expanduser("~/Library/Application Support/Aleria/aleria.sock")

def main():
    raw = sys.stdin.read()
    if not raw.strip():
        sys.exit(0)
    try:
        payload = json.loads(raw)
    except Exception:
        sys.exit(0)

    agent = "claude"
    wait_reply = False
    args = sys.argv[1:]
    for i, a in enumerate(args):
        if a == "--agent" and i + 1 < len(args):
            agent = args[i + 1]
        elif a in ("--ask", "--wait"):
            wait_reply = True

    event_name = payload.get("hook_event_name") or payload.get("event") or ""
    if event_name in ("PermissionRequest", "Stop") or payload.get("tool_name") == "AskUserQuestion":
        wait_reply = True

    payload["ia_agent"] = agent
    payload["term_program"] = os.environ.get("TERM_PROGRAM", "")
    payload["bundle_id"] = os.environ.get("__CFBundleIdentifier", "")

    if not os.path.exists(SOCK_PATH):
        sys.exit(0)

    s = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
    s.settimeout(118.0 if wait_reply else 0.4)
    try:
        s.connect(SOCK_PATH)
        s.sendall((json.dumps(payload) + "\n").encode("utf-8"))
        if wait_reply:
            resp = s.recv(16384).decode("utf-8", errors="ignore").strip()
            if resp:
                print(resp)
    except Exception:
        pass
    finally:
        try:
            s.close()
        except Exception:
            pass

if __name__ == "__main__":
    main()"
